import re
p_in = "/home/claude/review/build_review_v2.js"
p_out = "/home/claude/review/build_review_v3.js"
src = open(p_in, encoding="utf-8").read()

def rep(old, new, count=1):
    global src
    n = src.count(old)
    assert n == count, f"expected {count} match(es), found {n}: {old[:80]!r}"
    src = src.replace(old, new)

# ---- title line ----
rep("Prepared for Andrew Buggee, Scripps Institution of Oceanography — 2 November 2026 (revision 2, incorporating the outstanding problems of Hobbs, 1993)",
    "Prepared for Andrew Buggee, Scripps Institution of Oceanography — 9 November 2026 (revision 3: adds Section 11 on questions addressable within the EPCAPE turbulence–brightness project; revision 2 added the Hobbs, 1993, audit)")

# ---- abstract ----
rep("identifying which of those problems have been resolved and which remain open.\"));",
    "identifying which of those problems have been resolved and which remain open. A final section maps the open questions onto the DOE ASR project that funds this work, *Connecting Aerosol-Related Cloud Brightness to Turbulence using EPCAPE Measurements* (Miller et al., 2024), and identifies those that fall within its radiation and retrieval tasks without overlapping the turbulence work assigned to its principal investigator.\"));")

